    let cov = (&a * a.adjoint()).scale(3.0) + &b * b.adjoint();
    let noise = est.noise_subspace(&(cov + CMatrix::identity(n, n).scale(1e-3)), 2);
    assert_eq!(noise.ncols(), n - 2);
