            let e = err(&est, &data, n, &bins, doa as f64);
            if e > worst { worst = e; println!("  th {th} {freqs:?} {doa} nfft {n}: {e:.2} bins {bins:?}"); }
        }}}
        println!("PROBE composite th {th}: worst {worst:.2} maxbins {nb}");
    }
}

